STATIC = interface_directory()

if __name__ == "__main__":
    try:
        main()
    except (ValueError, ImportError) as error:
        print("Không thể khởi động: " + str(error), file=sys.stderr)
        raise SystemExit(1)
    except sqlite3.Error as error:
        print("Lỗi SQLite: " + str(error), file=sys.stderr)
        print("Kiểm tra quyền ghi tệp library.sqlite3 cạnh Source_code.py.")
        raise SystemExit(1)
